	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)

	scores := make(map[string]int)
	for range 3 {
		sc.Scan()
		f := strings.Fields(sc.Text())
		v, _ := strconv.Atoi(f[1])
		scores[f[0]] = v
	}

	// ここから下を書く: range で scores を回して合計を出力する
	_ = scores
	_ = fmt.Println
}

